@classmethod
def _restore_labels(cls, labels):
    if not isinstance(labels, (list, tuple)):
        raise SnapshotFormatError("labels must be an array of pairs")
    for item in labels:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
